    assert Range(3, 4, 2).as_relational(x) == Eq(x, 3)
    ranges = (
        Range(0), Range(3, 4, 2), Range(-3, 4),
        Range(3, oo, 2), Range(-oo, 3, 2),
        Range(-oo, oo),
    )
    values = [S(i)/2 for i in range(-12, 13)] + [-oo, oo, sqrt(2)]
    for r in ranges:
        for ordered in (r, r.reversed):
            condition = ordered.as_relational(x)
            for value in values:
                assert condition.subs(x, value) == ordered.contains(value)


